// Shuffle returns a copy of items in random order; the input is untouched.
func Shuffle[T any](items []T) []T {
	out := slice.Clone(items)
	for i := range len(out) {
		j := rand.Intn(i + 1)
		tmp := out[i]
		out[i] = out[j]
		out[j] = tmp
	}
	return out
}

// Sample returns n distinct elements of items in random order (partial
// Fisher–Yates). n is clamped to len(items); n <= 0 or an empty list yields an
// empty list. The input is untouched. The pick-k-of-these companion to Choice
// and Shuffle. NOT cryptographically secure — see package doc.
// Example: trio := random.Sample(deck, 3)
func Sample[T any](items []T, n int) []T {
	pool := slice.Clone(items)
	if n > len(pool) {
		n = len(pool)
	}
	out := []T{}
	for i := range n {
		j := i + rand.Intn(len(pool)-i)
		tmp := pool[i]
		pool[i] = pool[j]
		pool[j] = tmp
		out = append(out, pool[i])
	}
	return out
}

